import type { AbilityKey, CasterClass, SourceBook, Spell, SpellTag } from '@/types/dnd';

/**
 * Restante do Livro do Jogador (PHB 2014) — completa `spells.ts`.
 * Nomes em português, listas de classe oficiais e um resumo PARAFRASEADO
 * do efeito (sem o texto do livro). Formato compacto:
 *
 *   S(id, círculo, nome, escola, tempo, alcance, componentes, duração, classes, resumo, extras)
 *
 * escola: A abjuração · C conjuração · D adivinhação · E encantamento ·
 *         V evocação · I ilusão · N necromancia · T transmutação
 * classes: b bardo · c clérigo · d druida · p paladino · r patrulheiro ·
 *          s feiticeiro · k bruxo · w mago
 * tempo: A ação · B ação bônus · R reação · M 1 minuto · X 10 minutos · H 1 hora
 * duração: I instantânea · c1r/c1m/c10m/c1h/c8h/c24h concentração · resto literal
 */
const SCHOOL: Record<string, string> = {
  A: 'Abjuração', C: 'Conjuração', D: 'Adivinhação', E: 'Encantamento',
  V: 'Evocação', I: 'Ilusão', N: 'Necromancia', T: 'Transmutação',
};
const CLS: Record<string, CasterClass> = {
  b: 'bard', c: 'cleric', d: 'druid', p: 'paladin', r: 'ranger', s: 'sorcerer', k: 'warlock', w: 'wizard',
};
const CAST: Record<string, string> = {
  A: '1 ação', B: '1 ação bônus', R: 'Reação', M: '1 minuto', X: '10 minutos', H: '1 hora',
};
const CONC: Record<string, string> = {
  c1r: 'Concentração, até 1 rodada', c1m: 'Concentração, até 1 min', c10m: 'Concentração, até 10 min',
  c1h: 'Concentração, até 1 hora', c2h: 'Concentração, até 2 horas', c6r: 'Concentração, até 6 rodadas', c8h: 'Concentração, até 8 horas', c24h: 'Concentração, até 24 horas',
};

export interface Extra {
  ritual?: boolean;
  save?: AbilityKey;
  attack?: 'melee' | 'ranged';
  /** [dados, tipo] */
  dmg?: [string, string];
  heal?: string;
  area?: string;
  higher?: string;
  material?: string;
  conditions?: string[];
  tags?: SpellTag[];
}

export type SpellBuilder = (
  id: string, level: number, name: string, school: string, cast: string, range: string,
  components: string, duration: string, classes: string, desc: string, x?: Extra,
) => Spell;

/** Construtor compacto de magias com prefixo de id e livro de origem. */
export function spellBuilder(prefix: string, source?: SourceBook): SpellBuilder {
  return (...args) => ({ ...buildSpell(...args), id: `${prefix}-${args[0]}`, source });
}

const S: SpellBuilder = (...args) => buildSpell(...args);

function buildSpell(
  id: string, level: number, name: string, school: string, cast: string, range: string,
  components: string, duration: string, classes: string, desc: string, x: Extra = {},
): Spell {
  const tags = new Set<SpellTag>(x.tags ?? []);
  if (x.dmg) tags.add('dano');
  if (x.heal) tags.add('cura');
  if (!tags.size) tags.add('utilidade');
  return {
    id: `phb-${id}`,
    level,
    name,
    school: SCHOOL[school] ?? school,
    castingTime: CAST[cast] ?? cast,
    range,
    components,
    material: x.material,
    duration: duration === 'I' ? 'Instantânea' : CONC[duration] ?? duration,
    concentration: duration.startsWith('c') && !!CONC[duration],
    ritual: x.ritual,
    classes: classes.split('').map((c) => CLS[c]),
    desc,
    higher: x.higher,
    damage: x.dmg ? { dice: x.dmg[0], type: x.dmg[1] } : undefined,
    heal: x.heal,
    save: x.save,
    attack: x.attack,
    area: x.area,
    conditions: x.conditions?.map((c) => c[0].toUpperCase() + c.slice(1)),
    tags: [...tags],
  };
}

